    if not grid:
        return 0
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    visited = [[False]*cols for _ in range(rows)]
    dirs = [(1,0),(-1,0),(0,1),(0,-1)]
    def dfs(r,c):
        stack = [(r,c)]
        while stack:
            x,y = stack.pop()
            if visited[x][y]:
                continue
            visited[x][y] = True
            for dr,dc in dirs:
                nr, nc = x+dr, y+dc
                if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and grid[nr][nc]==1:
