{"task_id": "T35", "code": "def solve(grid: list[list[int]]) -> int:
    """Count islands in a possibly ragged grid.
    Cells are connected 4-directionally. Handles rows of differing lengths.
    """
    if not grid:
        return 0
    visited = set()
    rows = len(grid)
    def neighbors(r, c):
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < rows and 0 <= nc < len(grid[nr]):
                yield nr, nc
    islands = 0
    for r in range(rows):
        for c in range(len(grid[r])):
            if grid[r][c] == 1 and (r,c) not in visited:
                islands += 1
                # DFS stack
                stack = [(r,c)]
                while stack:
                    i,j = stack.pop()
                    if (i,j) in visited:
                        continue
                    visited.add((i,j))
                    for ni,nj in neighbors(i,j):
                        if grid[ni][nj] == 1 and (ni,nj) not in visited:
                            stack.append((ni,nj))
    return islands
"}

