def solve(grid):
    """Count islands in a grid where cells with value equivalent to 1 are land.
    Handles jagged rows and treats any value that converts to integer 1 as land.
    Connectivity is 4-directional.
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = set()
    def is_land(v):
        try:
            return int(v) == 1
        except Exception:
            return False
    def neighbors(r, c):
        for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < len(grid[nr]):
                yield nr, nc
    def bfs(sr, sc):
        stack = [(sr, sc)]
        while stack:
            r, c = stack.pop()
            if (r, c) in visited:
                continue
            visited.add((r, c))
            for nr, nc in neighbors(r, c):
                if (nr, nc) not in visited and is_land(grid[nr][nc]):
                    stack.append((nr, nc))
    count = 0
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if is_land(val) and (i, j) not in visited:
                bfs(i, j)
                count += 1
    return count

