def solve(tokens):
    # Reverse Polish notation evaluator supporting +, -, *, / with truncation toward zero.
    # Returns 0 for empty input.
    stack = []
    for t in tokens:
        if t in '+-*/':
            # Ensure there are enough operands; assume valid input per spec.
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                stack.append(a + b)
            elif t == '-':
                stack.append(a - b)
            elif t == '*':
                stack.append(a * b)
            else:  # division, truncate toward zero
                stack.append(int(a / b))
        else:
            stack.append(int(t))
    return stack[-1] if stack else 0

